function build(api) {
  api.name('PonyFoal');
  const C_COAT = 0x8b5a2b, C_COAT_DARK = 0x6b4420, C_CREAM = 0xF5DEB3, C_HOOF = 0x4a4a4a, C_EYE = 0x1c1c1c, C_NOSE = 0x5a3a1b;

  api.group('body','躯干');
    api.box({w:2.0,h:1.6,d:1.5,pos:[0,1.6,1.0],color:C_COAT});
    api.box({w:1.8,h:1.4,d:1.2,pos:[0,1.3,0],color:C_COAT});
    api.box({w:1.6,h:1.3,d:1.0,pos:[0,1.1,-1.0],color:C_COAT_DARK});
    api.box({w:1.8,h:1.5,d:1.2,pos:[0,1.3,-2.0],color:C_COAT});
    api.chain({waypoints:[[0,2.0,1.2],[0,2.8,1.8]],r:0.7,color:C_COAT});
  api.endGroup();

  api.group('head','头部');
    api.pivot([0,2.5,1.5],'body');
    api.box({w:1.4,h:1.3,d:1.2,pos:[0,3.2,2.5],color:C_COAT});
    api.box({w:1.0,h:0.9,d:1.2,pos:[0,2.8,3.5],color:C_COAT});
    api.box({w:0.9,h:0.3,d:1.0,pos:[0,2.4,3.3],color:C_COAT_DARK});
    api.poly({r:0.25,pos:[0.65,3.3,3.0],color:C_EYE});
    api.poly({r:0.25,pos:[-0.65,3.3,3.0],color:C_EYE});
    api.cone({r:0.2,h:0.6,along:'+Y',pos:[0.4,4.0,2.5],color:C_COAT});
    api.cone({r:0.2,h:0.6,along:'+Y',pos:[-0.4,4.0,2.5],color:C_COAT});
    api.sphere({r:0.08,pos:[0.3,2.6,4.1],color:C_NOSE});
    api.sphere({r:0.08,pos:[-0.3,2.6,4.1],color:C_NOSE});
  api.endGroup();

  const legData = [
    {id:'frontLeftLeg', sx:1, waypoints:[[0.9,1.6,1.0],[1.1,0.7,0.8],[1.0,0.15,0.9]], pivot:[0.9,1.6,1.0], rS:0.35},
    {id:'frontRightLeg', sx:-1, waypoints:[[-0.9,1.6,1.0],[-1.1,0.7,0.8],[-1.0,0.15,0.9]], pivot:[-0.9,1.6,1.0], rS:0.35},
    {id:'backLeftLeg', sx:1, waypoints:[[0.8,1.3,-2.0],[0.9,0.5,-1.5],[0.8,0.15,-1.8]], pivot:[0.8,1.3,-2.0], rS:0.4},
    {id:'backRightLeg', sx:-1, waypoints:[[-0.8,1.3,-2.0],[-0.9,0.5,-1.5],[-0.8,0.15,-1.8]], pivot:[-0.8,1.3,-2.0], rS:0.4}
  ];
  for(const leg of legData){
    api.group(leg.id);
    api.pivot(leg.pivot,'body');
    api.chain({waypoints:leg.waypoints,rStart:leg.rS,rEnd:0.25,jointIds:['joint1','joint2','joint3','paw'],color:C_COAT});
    api.box({w:0.5,h:0.3,d:0.5,pos:leg.waypoints[2],color:C_HOOF});
    api.endGroup();
  }

  api.group('mane','鬃毛');
    api.pivot([0,2.5,1.5],'body');
    api.box({w:1.2,h:0.8,d:0.5,pos:[0,3.7,2.8],color:C_CREAM});
    api.box({w:1.0,h:0.7,d:0.5,pos:[0,3.2,2.0],color:C_CREAM});
    api.box({w:0.9,h:0.6,d:0.5,pos:[0,2.8,1.4],color:C_CREAM});
    api.box({w:0.8,h:0.5,d:0.5,pos:[0,2.4,0.8],color:C_CREAM});
  api.endGroup();

  api.group('tail','尾巴');
    api.pivot([0,1.3,-2.5],'body');
    api.chain({waypoints:[[0,1.3,-2.8],[0,1.0,-3.5]],rStart:0.3,rEnd:0.2,color:C_COAT});
    api.box({w:1.0,h:1.5,d:0.5,pos:[0,0.5,-3.8],color:C_CREAM});
  api.endGroup();
}
